SELECT 
FROM chat_sessions
WHERE user_id = #{userId}
ORDER BY last_update_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM chat_sessions
WHERE user_id = #{userId}

SELECT 
FROM chat_sessions

    (
        user_id = #{userId}
        AND (biz_type IS NULL OR biz_type = '' OR biz_type NOT IN ('workflowTaskChat', 'workflow-task-chat', 'projectChat', 'project-chat'))
    )
    OR biz_type IN ('workflowTaskChat', 'workflow-task-chat', 'projectChat', 'project-chat')

        AND agent_id = #{agentId}


ORDER BY last_update_time DESC
